const where = [];
const params = [];
if (status !== 'all') {
    where.push('s.verify_status = ?');
    params.push(status);
}
const text = typeof q.q === 'string' ? q.q.trim().slice(0, 100) : '';
if (text) {
    const like = '%' + text.replace(/[\\%_]/g, (c) => '\\' + c) + '%';
    where.push('(s.name LIKE ? OR u.email LIKE ?)');
    params.push(like, like);
}
// Pending queue: oldest submission first; other lists: newest shop first
const order = status === 'pending' ? 's.verify_submitted_at ASC, s.id ASC' : 's.created_at DESC, s.id DESC';
