        minAge = b.minAge;
    }

    return {
        value: {
            title, description, categoryId, provinceId, districtId, wage, wageUnit: b.wageUnit,
            scheduleType: b.scheduleType, startDate, endDate, workDays: workDays.join(','),
            startTime: b.startTime, endTime: b.endTime, minAge,
        },
    };
}

