const routeId = (name = 'id') => (/^\d{1,10}$/.test(String(msg.req.params[name])) ? Number(msg.req.params[name]) : 0);

// A job seekers may see in search: open, not expired, schedule not over, shop verified, owner not suspended
const VISIBLE = `j.status = 'open' AND j.expires_on >= CURDATE()
    AND NOT (j.schedule_type = 'dates' AND j.end_date < CURDATE())
    AND s.verify_status = 'verified' AND u.status = 'active'`;
const SHOP_JOINS = `JOIN shops s ON s.id = j.shop_id
JOIN users u ON u.id = s.owner_user_id`;

try {
    const jobId = routeId();
    if (!jobId) throw sj.httpError(404, 'NOT_FOUND', 'ไม่พบประกาศนี้');
    const uid = msg.user.id;
    const app = await sj.tx(async (db) => {
        const [[job]] = await db.query(
            `SELECT j.id, j.title, j.min_age, s.owner_user_id, (${VISIBLE}) AS accepting
             FROM jobs j ${SHOP_JOINS}
             WHERE j.id = ? AND j.status <> 'hidden' AND s.verify_status = 'verified' AND u.status = 'active'`,
            [jobId],
        );
        if (!job) throw sj.httpError(404, 'NOT_FOUND', 'ไม่พบประกาศนี้');
        if (!job.accepting) throw sj.httpError(409, 'JOB_CLOSED', 'ประกาศนี้ปิดรับสมัครแล้ว');

        const [[me]] = await db.query('SELECT full_name, birth_date FROM seeker_profiles WHERE user_id = ?', [uid]);
        if (!me) throw sj.httpError(409, 'PROFILE_REQUIRED', 'กรุณากรอกโปรไฟล์ก่อน');
        if (job.min_age && sj.ageOn(me.birth_date, sj.today()) < job.min_age) {
            throw sj.httpError(403, 'AGE_REQUIREMENT', `งานนี้รับผู้สมัครอายุ ${job.min_age} ปีขึ้นไป`);
        }

        const [[existing]] = await db.query(
            'SELECT id, status FROM applications WHERE job_id = ? AND seeker_user_id = ? FOR UPDATE',
            [jobId, uid],
        );
        let id;
        if (existing) {
            // A cancelled application can be sent again (same row); anything else is a duplicate
            if (existing.status !== 'cancelled') throw sj.httpError(409, 'ALREADY_APPLIED', 'คุณสมัครงานนี้ไปแล้ว');
            await db.query(
                "UPDATE applications SET status = 'pending', applied_at = NOW(), decided_at = NULL, cancelled_at = NULL WHERE id = ?",
                [existing.id],
            );
            id = existing.id;
        } else {
            const [res] = await db.query('INSERT INTO applications (job_id, seeker_user_id) VALUES (?, ?)', [jobId, uid]);
            id = res.insertId;
        }
        await sj.notify(db, job.owner_user_id, 'application.new', `${me.full_name} สมัครงาน "${job.title}"`, `/shop/applicants/${id}`);
        return { id };
    });
    msg.statusCode = 201;
    msg.payload = { application: { id: app.id, status: 'pending' } };
    return msg;
} catch (e) {
    if (e instanceof sj.HttpError) return fail(e.status, e.code, e.message, e.details);
    throw e;
}

