// ?status=pending,accepted -> SQL condition on a.status ('' = all)
function statusFilter(text) {
    const all = ['pending', 'accepted', 'rejected', 'cancelled', 'completed'];
    if (!text || text === 'all') return { sql: '', params: [] };
    const list = String(text).split(',');
    if (list.some((s) => !all.includes(s))) return null;
    return { sql: ' AND a.status IN (?)', params: [list] };
}

