}
// Inserts the review; duplicate (same application + reviewer) -> 409
async function insertReview(db, appId, reviewer, reviewee, input) {
    const sj = global.get('sj');
    try {
        await db.query('INSERT INTO reviews (application_id, reviewer_user_id, reviewee_user_id, rating, comment) VALUES (?, ?, ?, ?, ?)',
            [appId, reviewer, reviewee, input.rating, input.comment]);
    } catch (e) {
        if (e.code === 'ER_DUP_ENTRY') throw sj.httpError(409, 'ALREADY_REVIEWED', 'คุณรีวิวใบสมัครนี้ไปแล้ว');
        throw e;
    }
}
